+class ZipSlipError(Exception):
+    """Exception raised when a zip slip attack is detected."""
+
+    pass
+
+
+def check_path_traversal(entry_name, dest_dir):
+    """
+    Check if an archive entry would extract outside the destination directory.
+    Raises ZipSlipError if path traversal is detected.
+    """
+    dest_dir = os.path.realpath(dest_dir)
+    target_path = os.path.realpath(os.path.join(dest_dir, entry_name))
+    if not target_path.startswith(dest_dir + os.sep) and target_path != dest_dir:
+        raise ZipSlipError(
+            f"Path traversal detected: '{entry_name}' would extract to '{target_path}' "
+            f"which is outside the target directory '{dest_dir}'"
+        )
+    return target_path
+
+
+def safe_extract_zip(zip_path, dest_dir):
+    """Safely extract a zip file, checking for path traversal."""
+    with zipfile.ZipFile(zip_path, "r") as zf:
+        for member in zf.namelist():
+            check_path_traversal(member, dest_dir)
+        zf.extractall(dest_dir)
+
+
+def safe_extract_tar(tar_path, dest_dir):
+    """Safely extract a tar file, checking for path traversal."""
+    with tarfile.open(tar_path) as tf:
+        for member in tf.getmembers():
+            check_path_traversal(member.name, dest_dir)
+            if member.issym() or member.islnk():
+                link_target = os.path.realpath(os.path.join(dest_dir, member.linkname))
+                if not link_target.startswith(os.path.realpath(dest_dir) + os.sep):
+                    raise ZipSlipError(
+                        f"Path traversal via symlink detected: '{member.name}' -> '{member.linkname}'"
+                    )
+        tf.extractall(dest_dir)
+
