+/// Verify the QE Identity signature against the signing certificate in the issuer chain
+fn verify_qe_identity_signature(collateral: &Collateral) -> Result<(), Error> {
+    let qe_identity = collateral
+        .qe_identity
+        .as_ref()
+        .ok_or(Error::InvalidQeIdentity)?;
+    let qe_identity_signature = collateral
+        .qe_identity_signature
+        .as_ref()
+        .ok_or(Error::InvalidQeIdentitySignature)?;
+    let qe_identity_issuer_chain = collateral
+        .qe_identity_issuer_chain
+        .as_ref()
+        .ok_or(Error::InvalidQeIdentityCertChain)?;
+
+    // Parse the issuer chain to get the signing certificate
+    let certs = parse_pem_certs(qe_identity_issuer_chain)?;
+    if certs.is_empty() {
+        return Err(Error::InvalidQeIdentityCertChain);
+    }
+
+    // The first certificate in the chain is the signing certificate
+    let signing_cert_der = &certs[0];
+    let (_, signing_cert) = X509Certificate::from_der(signing_cert_der)
+        .map_err(|_| Error::InvalidQeIdentityCertChain)?;
+
+    // Extract the public key from the signing certificate
+    let public_key = signing_cert
+        .public_key()
+        .parsed()
+        .map_err(|_| Error::InvalidQeIdentityCertChain)?;
+
+    // Decode the signature from hex
+    let sig_bytes =
+        hex::decode(qe_identity_signature).map_err(|_| Error::InvalidQeIdentitySignature)?;
+
+    // Verify the signature over the raw QE Identity JSON body
+    let qe_identity_body = qe_identity.as_bytes();
+
+    match public_key {
+        PublicKey::EC(ec_point) => {
+            let peer_public_key =
+                signature::UnparsedPublicKey::new(&signature::ECDSA_P256_SHA256_ASN1, ec_point.data());
+            peer_public_key
+                .verify(qe_identity_body, &sig_bytes)
+                .map_err(|_| Error::QeIdentitySignatureVerificationFailed)?;
+        }
+        PublicKey::RSA(rsa_key) => {
+            let peer_public_key = signature::UnparsedPublicKey::new(
+                &signature::RSA_PKCS1_2048_8192_SHA256,
+                rsa_key.as_ref(),
+            );
+            peer_public_key
+                .verify(qe_identity_body, &sig_bytes)
+                .map_err(|_| Error::QeIdentitySignatureVerificationFailed)?;
+        }
+        _ => return Err(Error::UnsupportedKeyAlgorithm),
+    }
+
+    Ok(())
+}
+
+/// Verify the QE Identity certificate chain (signing cert -> intermediate -> root)
+fn verify_qe_identity_cert_chain(collateral: &Collateral, now: u64) -> Result<(), Error> {
+    let qe_identity_issuer_chain = collateral
+        .qe_identity_issuer_chain
+        .as_ref()
+        .ok_or(Error::InvalidQeIdentityCertChain)?;
+    let root_ca = collateral
+        .root_ca
+        .as_ref()
+        .ok_or(Error::InvalidRootCa)?;
+
+    let certs = parse_pem_certs(qe_identity_issuer_chain)?;
+    if certs.len() < 2 {
+        return Err(Error::InvalidQeIdentityCertChain);
+    }
+
+    // Verify the chain: each cert is signed by the next, and the last is signed by root
+    verify_cert_chain(&certs, root_ca, now)?;
+
+    Ok(())
+}
