+    // Verify MRSIGNER matches the expected QE MRSIGNER from Intel's QE Identity
+    if let Some(ref expected_mrsigner) = qe_identity.mrsigner {
+        let expected_bytes = hex::decode(expected_mrsigner).map_err(|_| Error::InvalidQeIdentity)?;
