+        let expected = hex::decode(expected_attributes).map_err(|_| Error::InvalidQeIdentity)?;
+        let mask = hex::decode(attributes_mask).map_err(|_| Error::InvalidQeIdentity)?;
+        let report_attributes = qe_report.attributes.as_ref();
