+package org.apache.streampipes.rest.security;
+
+import org.apache.streampipes.model.extensions.svcdiscovery.SpServiceRegistration;
+import org.apache.streampipes.storage.management.StorageDispatcher;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.util.List;
+import java.util.Set;
+import java.util.stream.Collectors;
+
+/**
+ * Validates endpoint URLs against the list of registered StreamPipes extension services
+ * to prevent Server-Side Request Forgery (SSRF) attacks.
+ */
+public class EndpointUrlValidator {
+
+  private static final Logger LOG = LoggerFactory.getLogger(EndpointUrlValidator.class);
+
+  private static final Set<String> ALLOWED_SCHEMES = Set.of("http", "https");
+
+  private EndpointUrlValidator() {
+    // utility class
+  }
+
+  /**
+   * Validates that the given URL belongs to a registered StreamPipes extensions service endpoint.
+   *
+   * @param url the URL to validate
+   * @return true if the URL is from a registered extensions service, false otherwise
+   */
+  public static boolean isValidEndpointUrl(String url) {
+    if (url == null || url.isBlank()) {
+      return false;
+    }
+
+    try {
+      URI uri = new URI(url);
+
+      // Validate scheme
+      String scheme = uri.getScheme();
+      if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
+        LOG.warn("Rejected endpoint URL with disallowed scheme: {}", scheme);
+        return false;
+      }
+
+      String host = uri.getHost();
+      int port = uri.getPort();
+
+      if (host == null || host.isBlank()) {
+        LOG.warn("Rejected endpoint URL with missing host");
+        return false;
+      }
+
+      // Get all registered service endpoints
+      Set<String> allowedEndpoints = getRegisteredServiceEndpoints();
+
+      // Check if the URL's host:port matches any registered service
+      String requestEndpoint = host.toLowerCase() + (port > 0 ? ":" + port : "");
+      boolean isAllowed = allowedEndpoints.stream()
+          .anyMatch(endpoint -> requestEndpoint.equals(endpoint));
+
+      if (!isAllowed) {
+        LOG.warn("Rejected endpoint URL '{}' - host:port not in registered services", url);
+      }
+      return isAllowed;
+    } catch (URISyntaxException e) {
+      LOG.warn("Rejected malformed endpoint URL: {}", url);
+      return false;
+    }
+  }
+
+  private static Set<String> getRegisteredServiceEndpoints() {
+    List<SpServiceRegistration> registrations = StorageDispatcher.INSTANCE
+        .getNoSqlStore().getExtensionsServiceStorage().getAll();
+    return registrations.stream()
+        .map(reg -> (reg.getHost().toLowerCase() + ":" + reg.getPort()))
+        .collect(Collectors.toSet());
+  }
+}
