+/**
+ * Sanitize message content by neutralizing dangerous platform-specific tags
+ * that could be abused to trigger privileged behavior.
+ * @param {string} content - The raw user input
+ * @returns {string} - Sanitized content safe for sending
+ */
+function sanitizeMessage(content) {
+    if (typeof content !== 'string') return content;
+    // Neutralize all qqbot-* platform tags to prevent privilege escalation
+    // Matches self-closing and opening tags like <qqbot-at-everyone />, <qqbot-cmd-input ... />
+    return content
+        .replace(/<(\/?\s*qqbot-[a-z-]*)\s*([^>]*?)(\s*\/?)>/gi, (match, tag, attrs, close) => {
+            return `&lt;${tag}${attrs ? ' ' + attrs : ''}${close}&gt;`;
+        });
+}
+
+module.exports = {
+    sanitizeMessage
+};

