+/**
+ * Safely parses and validates a Content-Type header value.
+ * Strips any characters that are not valid in MIME types to prevent
+ * code injection attacks via crafted Content-Type headers.
+ *
+ * @param contentType - The raw Content-Type header value
+ * @returns The sanitized Content-Type string
+ */
+export function sanitizeContentType(contentType: string): string {
+  if (!contentType || typeof contentType !== 'string') {
+    return '';
+  }
+  // Only allow valid MIME type characters per RFC 6838
+  return contentType.replace(/[^\w\s\-+./;=]/gi, '');
+}
